mapper.select:
select DISTINCT
CAST(ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(d.longitude,d.latitude))*111195 as DECIMAL(65,2)) as distance,
d.id, d.resource_id, d.resource_name, d.resource_type_id, z.resource_type_name, d.order_num, d.`status`, d.delete_flag, d.creator, d.create_time, d.modifier, d.update_time, d.tenant_id, s.tenant_name, d.remark, CASE WHEN d.resource_property = '1' THEN d.longitude WHEN d.resource_property = '2' THEN '' WHEN d.resource_property = '3' THEN '' END as longitude, CASE WHEN d.resource_property = '1' THEN d.latitude WHEN d.resource_property = '2' THEN '' WHEN d.resource_property = '3' THEN '' END as latitude, d.elevation, d.addr, d.industry_code, d.app_ver_code, CASE WHEN d.resource_property = '1' THEN '点资源' WHEN d.resource_property = '2' THEN '线资源' WHEN d.resource_property = '3' THEN '面资源' END as resource_property, a.area_name as province_name, b.area_name as city_name, z.icon, d.admin, d.tel from resource_conf d left join resource_type z on d.resource_type_id=z.resource_type_id and d.tenant_id = z.tenant_id and d.industry_code = z.industry_code left join sys_tenant_info s on d.tenant_id = s.tenant_id left join sys_area a on a.area_code=s.province_id left join sys_area b on b.area_code=s.city_id where d.delete_flag = 0 and z.delete_flag = 0
AND d.resource_name like CONCAT(CONCAT('%',#{resourceName}),'%')
AND z.resource_type_name like CONCAT(CONCAT('%',#{resourceTypeName}),'%')
AND z.type_level_url like CONCAT(CONCAT('%',#{typeLevelUrl}),'%')
AND d.longitude = #{longitudeParam}
AND d.latitude = #{latitudeParam}
AND d.elevation = #{elevation}
AND s.tenant_name like CONCAT(CONCAT('%',#{tenantName}),'%')
AND d.tenant_id = #{tenantId}
AND d.industry_code = #{industryCode}
AND d.app_ver_code = #{appVerCode}
AND d.resource_property = #{resourceProperty}
and ST_DISTANCE(POINT(#{longitude},#{latitude}),POINT(d.longitude,d.latitude))*111195 <= #{radius}
AND d.resource_type_id IN
#{item}
ORDER BY CONVERT(z.resource_type_name USING GBK)
desc
order by d.elevation + 0
desc
order by d.update_time desc
